# -*- coding: utf-8 -*-
"""Offline preview, task-A analysis and replay worker for mcp-dm.

Run by server.mjs with one JSON request on stdin. This uses an external Python
environment; it never imports the Gatan host module or edits a DM image.
"""
import csv
import hashlib
import importlib.util
import json
import math
import os
import shutil
import sys
import time
import uuid

# Keep generated bytecode out of user result directories, including replay runs.
sys.dont_write_bytecode = True

import numpy as np
# Only the requested capability loads its optional display dependencies.
# State inspection and numerical verification need NumPy, not a plotting stack.
Image = ImageDraw = matplotlib = plt = None


def _require_preview():
    global Image, ImageDraw
    if Image is None:
        try:
            from PIL import Image as image_module, ImageDraw as draw_module
        except ImportError as exc:
            raise RuntimeError("Preview requires requirements-preview.txt in the external Python environment; do not change GMS: %s" % exc)
        Image, ImageDraw = image_module, draw_module


def _require_report():
    global matplotlib, plt
    _require_preview()
    if plt is None:
        try:
            import matplotlib as plotting_module
            plotting_module.use("Agg")
            import matplotlib.pyplot as pyplot_module
        except ImportError as exc:
            raise RuntimeError("Optional report rendering requires requirements-analysis.txt in the external Python environment: %s" % exc)
        matplotlib, plt = plotting_module, pyplot_module


HERE = os.path.dirname(os.path.abspath(__file__))
CORE_PATHS = [os.path.join(HERE, "analysis2d_core.py"),
              os.path.join(HERE, "..", "bridge", "analysis2d_core.py")]
CORE_PATH = next((os.path.abspath(p) for p in CORE_PATHS if os.path.isfile(p)), None)
if CORE_PATH is None:
    raise RuntimeError("analysis2d_core.py not found")
_spec = importlib.util.spec_from_file_location("dm_mcp_analysis2d_core", CORE_PATH)
core = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(core)

ANALYSIS_MEMORY_BUDGET = 512 * 1024 * 1024
PNG_INLINE_LIMIT = 2 * 1024 * 1024
PREVIEW_MEMORY_BUDGET = 256 * 1024 * 1024
PREVIEW_TILE_SIDE = 512


def _canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def _sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        while True:
            block = stream.read(1024 * 1024)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()


def _read_json(path):
    with open(path, "r", encoding="utf-8") as stream:
        return json.load(stream)


def _write_json(path, value, exclusive=True):
    mode = "x" if exclusive else "w"
    with open(path, mode, encoding="utf-8", newline="\n") as stream:
        json.dump(value, stream, ensure_ascii=False, sort_keys=True,
                  indent=2, allow_nan=False)
        stream.write("\n")


def _manifest_path(folder):
    return os.path.join(folder, "manifest.json")


def _capture(capture_dir):
    folder = os.path.abspath(capture_dir)
    manifest = _read_json(os.path.join(folder, "capture.json"))
    info = _read_json(os.path.join(folder, "input.json"))
    if manifest.get("state") != "captured":
        raise ValueError("capture package is not in captured state")
    if info.get("capture_id") != manifest.get("capture_id"):
        raise ValueError("capture identity mismatch")
    metadata_hash = hashlib.sha256(_canonical(info)).hexdigest()
    if metadata_hash != manifest.get("input_metadata_sha256"):
        raise ValueError("capture metadata hash mismatch; calibration or provenance may have changed")
    path = os.path.join(folder, info.get("input_file", "input.npy"))
    if os.path.basename(path) != "input.npy":
        raise ValueError("capture input file must be input.npy")
    actual_hash = _sha256_file(path)
    if actual_hash != info.get("input_sha256") or actual_hash != manifest.get("input_sha256"):
        raise ValueError("captured input hash mismatch; package may have changed")
    array = np.load(path, mmap_mode="r", allow_pickle=False)
    if array.ndim != 2 or list(array.shape) != info.get("shape_yx"):
        raise ValueError("captured NPY shape does not match input metadata")
    if str(array.dtype) != info.get("dtype") or array.dtype.kind not in "biuf":
        raise ValueError("captured NPY dtype is unsupported or does not match metadata")
    if array.dtype.kind in "iu" and array.dtype.itemsize >= 8:
        # Exact source bytes remain preserved, but float64 calculations cannot
        # represent every int64/uint64 value. Do not silently claim precision.
        values = np.asarray(array)
        if values.size and (int(values.min()) < -(2 ** 53) or int(values.max()) > 2 ** 53):
            raise ValueError("integer values exceed exact float64 analysis range; refusing lossy calculations")
    return folder, manifest, info, array


def _finite_range(array):
    """Scan bounded tiles, never make a full-frame finite mask or value copy."""
    low = high = None
    count = 0
    h, w = array.shape
    for y in range(0, h, PREVIEW_TILE_SIDE):
        for x in range(0, w, PREVIEW_TILE_SIDE):
            tile = np.asarray(array[y:y + PREVIEW_TILE_SIDE, x:x + PREVIEW_TILE_SIDE])
            finite = tile[np.isfinite(tile)]
            if finite.size:
                lo, hi = float(finite.min()), float(finite.max())
                low = lo if low is None else min(low, lo)
                high = hi if high is None else max(high, hi)
                count += int(finite.size)
    return low, high, count


def _gray_image(array, display_range=None):
    _require_preview()
    a = np.asarray(array)
    finite = np.isfinite(a)
    low, high, count = _finite_range(a) if display_range is None else display_range
    out = np.zeros(a.shape, dtype=np.uint8)
    if count:
        if high == low:
            out[finite] = 128
        else:
            scaled = np.zeros(a.shape, dtype=np.float64)
            # Normalize first to avoid overflow for opposite-sign finite extrema.
            norm = max(abs(low), abs(high))
            scaled[finite] = np.clip((a[finite].astype(np.float64) / norm - low / norm) /
                                     (high / norm - low / norm), 0, 1)
            out[finite] = np.rint(scaled[finite] * 255).astype(np.uint8)
    rgb = np.repeat(out[:, :, None], 3, axis=2)
    rgb[~finite] = (255, 0, 255)
    return Image.fromarray(rgb), {"display_mode": "linear min-max stretch over finite values",
        "display_min": low, "display_max": high, "finite_pixels": count,
        "nonfinite_display": "magenta", "constant_finite_display": "mid-gray (128)"}


def _source_rect(info):
    return list(info["source_rect_xyxy"])


def _checked_roi(roi, info):
    sx0, sy0, sx1, sy1 = _source_rect(info)
    if roi is None:
        return [sx0, sy0, sx1, sy1]
    if not isinstance(roi, list) or len(roi) != 4 or any(isinstance(x, bool) or not isinstance(x, int) for x in roi):
        raise ValueError("roi must be four integer source-pixel edges [x0,y0,x1,y1]")
    x0, y0, x1, y1 = roi
    if x1 <= x0 or y1 <= y0:
        raise ValueError("roi must have positive area")
    if x0 < sx0 or y0 < sy0 or x1 > sx1 or y1 > sy1:
        raise ValueError("roi must be fully inside the captured source rectangle; no clipping")
    return [x0, y0, x1, y1]


def _checked_profile(profile, info):
    if profile is None:
        return None
    if not isinstance(profile, dict) or set(profile) - {"start", "end", "width"}:
        raise ValueError("profile must contain start, end, and optional width")
    if "start" not in profile or "end" not in profile:
        raise ValueError("profile requires start and end source pixel centers")
    points = []
    sx0, sy0, sx1, sy1 = _source_rect(info)
    for label in ("start", "end"):
        pair = profile[label]
        if not isinstance(pair, list) or len(pair) != 2 or any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) for v in pair):
            raise ValueError("profile %s must be finite [x,y] source pixel centers" % label)
        x, y = float(pair[0]), float(pair[1])
        if not (sx0 <= x <= sx1 - 1 and sy0 <= y <= sy1 - 1):
            raise ValueError("profile endpoints must lie within captured pixel centers")
        points.append([x, y])
    width = profile.get("width", 1)
    if isinstance(width, bool) or not isinstance(width, int) or width < 1 or width > 1024:
        raise ValueError("profile width must be an integer from 1 to 1024 pixels")
    return {"start": points[0], "end": points[1], "width": width}


def _local_calibration(info, x0, y0):
    result = []
    for axis, offset in (("x", x0), ("y", y0)):
        rec = next((r for r in info["working_calibration_xy"] if r.get("axis") == axis), None)
        if rec is None:
            raise ValueError("missing %s calibration record" % axis)
        scale = rec.get("scale")
        origin = rec.get("calibrated_value_at_pixel_zero")
        if scale is not None and (not isinstance(scale, (int, float)) or not math.isfinite(scale)):
            raise ValueError("nonfinite %s scale" % axis)
        if origin is not None and (not isinstance(origin, (int, float)) or not math.isfinite(origin)):
            raise ValueError("nonfinite %s physical origin" % axis)
        shifted = None if origin is None or scale is None else float(origin) + offset * float(scale)
        result.append({"axis": axis, "scale": scale, "unit": rec.get("unit"),
                       "calibrated_value_at_pixel_zero": shifted})
    return result


def _relative_roi(roi, src):
    x0, y0, x1, y1 = roi
    sx0, sy0, _, _ = src
    return [x0 - sx0, y0 - sy0, x1 - sx0, y1 - sy0]


def _preview_image(array, info, max_side, roi=None, profile=None, output_path=None):
    if isinstance(max_side, bool) or not isinstance(max_side, int) or max_side < 32 or max_side > 4096:
        raise ValueError("max_side must be an integer from 32 to 4096")
    h, w = array.shape
    ratio = min(1.0, max_side / float(max(h, w)))
    pw, ph = max(1, int(round(w * ratio))), max(1, int(round(h * ratio)))
    # Allocate display buffers only at the requested output resolution. The
    # source remains a read-only memmap; small tiles determine its finite range.
    estimated = (pw * ph * (array.dtype.itemsize + 64) +
                 PREVIEW_TILE_SIDE ** 2 * (array.dtype.itemsize + 2) + 65536)
    if estimated > PREVIEW_MEMORY_BUDGET:
        raise RuntimeError("preview workspace exceeds budget; explicitly reduce max_side")
    display_range = _finite_range(array)
    if (pw, ph) == (w, h):
        shown = array
    else:
        columns = ((2 * np.arange(pw, dtype=np.int64) + 1) * w) // (2 * pw)
        rows = ((2 * np.arange(ph, dtype=np.int64) + 1) * h) // (2 * ph)
        shown = array[np.ix_(rows, columns)]
    base, display = _gray_image(shown, display_range)
    display.update({"resampling": "nearest source pixel to each preview pixel center; display only; small features may be missed",
                    "range_scope": "all finite pixels of the capture, scanned in bounded tiles",
                    "workspace_estimate_bytes": estimated,
                    "workspace_budget_bytes": PREVIEW_MEMORY_BUDGET})
    draw = ImageDraw.Draw(base)
    src = _source_rect(info)
    sx0, sy0 = src[0], src[1]
    def edge_xy(x, y):
        return ((x - sx0) * pw / float(w), (y - sy0) * ph / float(h))
    def center_xy(x, y):
        return (int(math.floor((x - sx0 + 0.5) * pw / float(w))),
                int(math.floor((y - sy0 + 0.5) * ph / float(h))))
    overlay = {"roi_source_xyxy": roi, "profile_source": profile}
    if roi is not None:
        rx0, ry0, rx1, ry1 = roi
        points = [edge_xy(rx0, ry0), edge_xy(rx1, ry0), edge_xy(rx1, ry1), edge_xy(rx0, ry1), edge_xy(rx0, ry0)]
        draw.line(points, fill=(255, 32, 32), width=max(1, int(round(2 * ratio))))
    if profile is not None:
        (x0, y0), (x1, y1) = profile["start"], profile["end"]
        length = math.hypot(x1 - x0, y1 - y0)
        nx, ny = (-(y1 - y0) / length, (x1 - x0) / length) if length else (0.0, 1.0)
        half = profile["width"] / 2.0
        corners = [(x0 + nx * half, y0 + ny * half),
                   (x1 + nx * half, y1 + ny * half),
                   (x1 - nx * half, y1 - ny * half),
                   (x0 - nx * half, y0 - ny * half)]
        polygon = [edge_xy(x + 0.5, y + 0.5) for x, y in corners]
        draw.line(polygon + [polygon[0]], fill=(32, 128, 255), width=max(1, int(round(1.5 * ratio))))
        draw.line([center_xy(x0, y0), center_xy(x1, y1)], fill=(0, 255, 64), width=max(1, int(round(2 * ratio))))
        draw.ellipse((center_xy(x0, y0)[0] - 2, center_xy(x0, y0)[1] - 2,
                      center_xy(x0, y0)[0] + 2, center_xy(x0, y0)[1] + 2), fill=(255, 255, 0))
        draw.ellipse((center_xy(x1, y1)[0] - 2, center_xy(x1, y1)[1] - 2,
                      center_xy(x1, y1)[0] + 2, center_xy(x1, y1)[1] + 2), fill=(255, 255, 0))
    if output_path:
        with open(output_path, "xb") as stream:
            base.save(stream, format="PNG", optimize=True)
    mapping = {
        "source_rect_xyxy": src, "source_shape_yx": list(info["source_shape_yx"]),
        "captured_shape_yx": [h, w], "preview_shape_yx": [ph, pw],
        "display_edge_to_source_edge": {
            "x": "source_x_edge = %d + preview_x_edge * %d/%d" % (sx0, w, pw),
            "y": "source_y_edge = %d + preview_y_edge * %d/%d" % (sy0, h, ph),
        },
        "display_center_to_source_pixel_center": {
            "x": "source_x = %d + (preview_x + 0.5) * %d/%d - 0.5" % (sx0, w, pw),
            "y": "source_y = %d + (preview_y + 0.5) * %d/%d - 0.5" % (sy0, h, ph),
        },
        "coordinates": "source coordinates are original image pixel coordinates; x right, y down; pixel centers are integer indices; ROI edges are half-open",
        "display": display, "overlay": overlay,
    }
    return base, mapping


def preview(payload):
    folder, manifest, info, array = _capture(payload["capture_dir"])
    roi = _checked_roi(payload.get("roi"), info) if payload.get("roi") is not None else None
    profile = _checked_profile(payload.get("profile"), info)
    max_side = payload.get("max_side", 1024)
    out_dir = os.path.join(folder, "previews")
    if not os.path.isdir(out_dir):
        try:
            os.makedirs(out_dir)
        except OSError:
            if not os.path.isdir(out_dir):
                raise
    output = os.path.join(out_dir, "preview-" + uuid.uuid4().hex + ".png")
    _, mapping = _preview_image(array, info, max_side, roi, profile, output)
    return {"state": "complete", "capture_id": info["capture_id"],
            "source_image_id": info.get("source_image_id"),
            "working_calibration_xy": info["working_calibration_xy"],
            "calibration_coordinate_frame": "captured pixel centers; source coordinates subtract source_rect_xyxy origin first",
            "intensity_calibration": info.get("intensity_calibration"),
            "intensity_values": "raw pixels; intensity origin/scale have not been applied",
            "input_metadata_sha256": manifest["input_metadata_sha256"],
            "input_sha256": info["input_sha256"], "preview_path": output,
            "preview_sha256": _sha256_file(output), "preview_bytes": os.path.getsize(output),
            "mapping": mapping, "same_input_for_computation": "capture package input.npy"}


def _copy_exclusive(source, target):
    with open(target, "xb") as dst, open(source, "rb") as src:
        shutil.copyfileobj(src, dst, 1024 * 1024)


def _atomic_manifest(path, manifest):
    tmp = path + ".tmp-" + uuid.uuid4().hex
    _write_json(tmp, manifest)
    os.replace(tmp, path)


def _output_hashes(folder):
    result = {}
    for root, dirs, files in os.walk(folder):
        dirs[:] = sorted(d for d in dirs if d not in ("__pycache__",))
        for name in sorted(files):
            path = os.path.join(root, name)
            rel = os.path.relpath(path, folder).replace(os.sep, "/")
            if rel == "manifest.json" or ".tmp-" in name:
                continue
            result[rel] = {"sha256": _sha256_file(path), "bytes": os.path.getsize(path)}
    return result


def _calibrated_fft_metadata(calibration, shape):
    h, w = shape
    x, y = calibration
    def axis(rec, size):
        scale = rec.get("scale")
        unit = rec.get("unit")
        if scale is None or scale == 0 or not math.isfinite(float(scale)) or not unit:
            return {"frequency_unit": "cycles/pixel", "sample_scale": None,
                    "sample_unit": None, "formula": "fftshift(fftfreq(N))"}
        return {"frequency_unit": "cycles/%s" % unit, "sample_scale": float(scale),
                "sample_unit": unit,
                "formula": "fftshift(fftfreq(N, d=sample_scale)); signed scale is retained"}
    return {"shape_yx": [h, w], "x": axis(x, w), "y": axis(y, h),
            "array_convention": "fftshifted absolute unnormalized DFT; row=frequency_y, column=frequency_x"}


def _save_analysis_figures(folder, array, info, roi, profile_result, fft_array, fft_meta):
    _require_report()
    src = _source_rect(info)
    full = os.path.join(folder, "input_preview.png")
    overlay = os.path.join(folder, "selection_overlay.png")
    _preview_image(array, info, 1400, None, None, full)
    _preview_image(array, info, 1400, roi, profile_result.get("request") if profile_result else None, overlay)
    if profile_result:
        values = np.asarray([np.nan if v is None else v for v in profile_result["values"]], dtype="float64")
        fig, ax = plt.subplots(figsize=(7, 4), constrained_layout=True)
        ax.plot(profile_result["distance"], values, linewidth=1.2)
        ax.set_xlabel("Distance (%s)" % profile_result["unit"])
        ax.set_ylabel("Raw pixel value (intensity calibration not applied)")
        ax.set_title("Bilinear line profile; width=%d px" % profile_result["width"])
        ax.grid(True, alpha=0.25)
        fig.savefig(os.path.join(folder, "profile.png"), dpi=150)
        plt.close(fig)
    rx0, ry0, _, _ = roi
    xrec, yrec = _local_calibration(info, rx0 - src[0], ry0 - src[1])
    h, w = fft_array.shape
    xscale, yscale = xrec.get("scale"), yrec.get("scale")
    calibrated_x = xscale is not None and xscale != 0 and xrec.get("unit")
    calibrated_y = yscale is not None and yscale != 0 and yrec.get("unit")
    fx = np.fft.fftshift(np.fft.fftfreq(w, d=float(xscale))) if calibrated_x else np.fft.fftshift(np.fft.fftfreq(w))
    fy = np.fft.fftshift(np.fft.fftfreq(h, d=float(yscale))) if calibrated_y else np.fft.fftshift(np.fft.fftfreq(h))
    def bin_edges(centers, scale, calibrated):
        if len(centers) == 1:
            step = 1.0 / (len(centers) * float(scale)) if calibrated else 1.0
            return [float(centers[0] - step / 2.0), float(centers[0] + step / 2.0)]
        values = np.empty(len(centers) + 1, dtype="float64")
        values[1:-1] = (centers[:-1] + centers[1:]) / 2.0
        values[0] = centers[0] - (centers[1] - centers[0]) / 2.0
        values[-1] = centers[-1] + (centers[-1] - centers[-2]) / 2.0
        return values.tolist()
    xedges = bin_edges(fx, xscale, bool(calibrated_x))
    yedges = bin_edges(fy, yscale, bool(calibrated_y))
    xunit = "cycles/%s" % xrec["unit"] if calibrated_x else "cycles/pixel"
    yunit = "cycles/%s" % yrec["unit"] if calibrated_y else "cycles/pixel"
    fig, ax = plt.subplots(figsize=(6, 5), constrained_layout=True)
    image = ax.imshow(np.log1p(fft_array), origin="lower", cmap="magma", aspect="auto",
                      extent=[xedges[0], xedges[-1], yedges[0], yedges[-1]])
    ax.set_xlabel("Frequency x (%s)" % xunit)
    ax.set_ylabel("Frequency y (%s)" % yunit)
    ax.set_title("log1p of full |FFT|; display only")
    fig.colorbar(image, ax=ax, label="log(1 + magnitude)")
    fig.savefig(os.path.join(folder, "fft.png"), dpi=150)
    plt.close(fig)


def _recursive_numeric_equal(left, right, rtol=1e-10, atol=1e-12, path="root"):
    if isinstance(left, dict) and isinstance(right, dict):
        if set(left) != set(right):
            return False, path + ": keys differ"
        for key in left:
            good, why = _recursive_numeric_equal(left[key], right[key], rtol, atol, path + "." + key)
            if not good:
                return good, why
        return True, ""
    if isinstance(left, list) and isinstance(right, list):
        if len(left) != len(right):
            return False, path + ": lengths differ"
        for i, (a, b) in enumerate(zip(left, right)):
            good, why = _recursive_numeric_equal(a, b, rtol, atol, "%s[%d]" % (path, i))
            if not good:
                return good, why
        return True, ""
    if isinstance(left, (int, float)) and not isinstance(left, bool) and isinstance(right, (int, float)) and not isinstance(right, bool):
        if math.isfinite(float(left)) and math.isfinite(float(right)):
            return abs(float(left) - float(right)) <= atol + rtol * abs(float(right)), path
    return left == right, path


def _profile_result(array, info, request):
    sx0, sy0 = _source_rect(info)[:2]
    (px0, py0), (px1, py1) = request["start"], request["end"]
    result = core.profile(array, _local_calibration(info, 0, 0),
                          px0 - sx0, py0 - sy0, px1 - sx0, py1 - sy0, request["width"])
    local = result["sampled_coordinates"]
    result.update({"sampled_coordinates_local": local,
                   "sampled_coordinates": [[x + sx0, y + sy0] for x, y in local],
                   "coordinate_frame": "original source pixel centers",
                   "local_coordinate_frame": "captured array pixel centers",
                   "calibration_coordinate_frame": "captured array pixel centers",
                   "request": request,
                   "intensity_value_mode": "raw pixel values; intensity calibration retained but not applied",
                   "intensity_calibration": info.get("intensity_calibration")})
    return result


def _compute(capture_dir, params, result_dir, operation_id):
    folder, capture_manifest, info, array = _capture(capture_dir)
    roi = _checked_roi(params.get("roi"), info)
    profile_request = _checked_profile(params.get("profile"), info)
    top_n = params.get("top_n", 12)
    if isinstance(top_n, bool) or not isinstance(top_n, int) or not 1 <= top_n <= 200:
        raise ValueError("top_n must be an integer from 1 to 200")
    rel_roi = _relative_roi(roi, _source_rect(info))
    x0, y0, x1, y1 = rel_roi
    selected_shape = (y1 - y0, x1 - x0)
    pixels = selected_shape[0] * selected_shape[1]
    estimated = pixels * 64 + 65536
    if estimated > ANALYSIS_MEMORY_BUDGET:
        raise RuntimeError("estimated 2D analysis workspace %d bytes exceeds %d; reduce ROI explicitly"
                           % (estimated, ANALYSIS_MEMORY_BUDGET))
    core_hash = _sha256_file(CORE_PATH)
    worker_hash = _sha256_file(__file__)
    params_normal = {"roi_source_xyxy": roi, "profile_source": profile_request, "top_n": top_n,
                    "method": "finite-population-stats; bilinear profile; mean-subtracted rectangular unnormalized absolute DFT"}
    request_identity = {"capture_id": info["capture_id"], "input_sha256": info["input_sha256"],
                        "input_metadata_sha256": capture_manifest["input_metadata_sha256"],
                        "params": params_normal, "analysis_core_sha256": core_hash,
                        "analysis_worker_sha256": worker_hash}
    request_hash = hashlib.sha256(_canonical(request_identity)).hexdigest()
    result_dir = os.path.abspath(result_dir)
    if os.path.exists(result_dir):
        existing_path = _manifest_path(result_dir)
        if not os.path.isfile(existing_path):
            raise FileExistsError("result_dir exists without a manifest; refusing to overwrite or reuse it")
        existing = _read_json(existing_path)
        if existing.get("operation_id") != operation_id or existing.get("request_sha256") != request_hash:
            raise ValueError("operation_id/result_dir is already bound to different input or parameters")
        return inspect_result({"result_dir": result_dir}, expected_operation_id=operation_id)
    _require_report()  # Fail before reserving a result directory when deps are absent.
    os.makedirs(result_dir)
    started = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    manifest = {"schema_version": 1, "operation_id": operation_id,
                "operation_scope": "this result_dir; query this folder after client timeout",
                "state": "running", "request_sha256": request_hash,
                "capture_id": info["capture_id"], "input_sha256": info["input_sha256"],
                "params": params_normal, "estimated_peak_bytes": estimated,
                "analysis_memory_budget_bytes": ANALYSIS_MEMORY_BUDGET,
                "started_utc": started, "analysis_core_sha256": core_hash}
    manifest["analysis_worker_sha256"] = worker_hash
    manifest_path = _manifest_path(result_dir)
    _write_json(manifest_path, manifest)
    try:
        copied_info = dict(info)
        _copy_exclusive(os.path.join(folder, "input.npy"), os.path.join(result_dir, "input.npy"))
        _copy_exclusive(os.path.join(folder, "input.json"), os.path.join(result_dir, "input.json"))
        _copy_exclusive(os.path.join(folder, "capture.json"), os.path.join(result_dir, "capture.json"))
        _write_json(os.path.join(result_dir, "request.json"), {
            "operation_id": operation_id, "capture_dir_reference": "not stored",
            "capture_id": info["capture_id"], "input_sha256": info["input_sha256"],
            "request_sha256": request_hash, "params": params_normal,
            "source_rect_xyxy": _source_rect(info),
            "source_rect_convention": "zero-based half-open; profile points are pixel centers",
            "calibration": info["working_calibration_xy"]})
        selected = np.asarray(array[y0:y1, x0:x1])
        stats = core.statistics(selected)
        stats.update({"roi_source_xyxy": roi, "roi_local_xyxy": rel_roi,
                      "shape_yx": list(selected.shape), "calibration_xy": _local_calibration(info, rel_roi[0], rel_roi[1]),
                      "intensity_calibration": info.get("intensity_calibration"),
                      "intensity_value_mode": "raw pixel values; intensity calibration retained but not applied",
                      "finite_policy": "finite pixels only; NaN/Inf excluded and separately counted; population stddev ddof=0; zero values retained"})
        _write_json(os.path.join(result_dir, "stats.json"), stats)
        profile_result = None
        if profile_request is not None:
            profile_result = _profile_result(array, info, profile_request)
            with open(os.path.join(result_dir, "profile.csv"), "x", newline="", encoding="utf-8") as stream:
                writer = csv.writer(stream)
                writer.writerow(["distance_" + profile_result["unit"], "raw_intensity", "finite_samples"])
                for distance, value, count in zip(profile_result["distance"], profile_result["values"], profile_result["finite_samples_per_point"]):
                    writer.writerow(["%.17g" % distance, "" if value is None else "%.17g" % value, count])
            _write_json(os.path.join(result_dir, "profile.json"), profile_result)
        fft_result, fft_values = core.fft(selected, _local_calibration(info, rel_roi[0], rel_roi[1]), top_n)
        fft_metadata = _calibrated_fft_metadata(fft_result["calibration"], fft_values.shape)
        fft_result.update({"roi_source_xyxy": roi, "roi_local_xyxy": rel_roi,
                           "shape_yx": list(fft_values.shape), "axes": fft_metadata})
        with open(os.path.join(result_dir, "fft_magnitude.npy"), "xb") as stream:
            np.save(stream, fft_values, allow_pickle=False)
        _write_json(os.path.join(result_dir, "fft.json"), fft_result)
        _save_analysis_figures(result_dir, array, copied_info, roi,
                               dict(profile_result, request=profile_request) if profile_result else None,
                               fft_values, fft_metadata)
        env = {"python": sys.version.split()[0], "numpy": np.__version__,
               "matplotlib": matplotlib.__version__, "pillow": Image.__version__,
               "platform": sys.platform, "worker_sha256": _sha256_file(__file__),
               "analysis_core_sha256": core_hash}
        facts = ["Captured input hash: %s" % info["input_sha256"],
                 "Source-coordinate ROI [x0,y0,x1,y1): %s" % roi,
                 "Finite-value statistics: n=%d/%d; mean=%.12g; population stddev=%.12g" %
                    (stats["finite_count"], stats["total_count"], stats["mean"], stats["stddev"]),
                 "FFT: full shifted absolute magnitude saved as fft_magnitude.npy; mean removed, rectangular window, no normalization."]
        if profile_result:
            facts.append("Profile: source pixel centers %s to %s, width %d px, %d points; x-axis unit %s." %
                         (profile_request["start"], profile_request["end"], profile_request["width"],
                          profile_result["n"], profile_result["unit"]))
        report = "# Optional 2D analysis example\n\n"
        report += "## Input and calibration\n\n"
        report += "- Captured selection shape: %s (y,x); source rectangle: %s [x0,y0,x1,y1), half-open.\n" % (info["shape_yx"], _source_rect(info))
        for axis in stats["calibration_xy"]:
            report += "- %s: scale `%s`, unit `%s`, calibrated value at ROI pixel zero `%s`.\n" % (
                axis["axis"], axis["scale"], axis["unit"], axis["calibrated_value_at_pixel_zero"])
        report += "\n## Computed facts\n\n" + "\n".join("- " + v for v in facts)
        report += "\n\n## Figures\n\n"
        report += "![Captured input preview](input_preview.png)\n\n"
        report += "![ROI and profile overlay](selection_overlay.png)\n\n"
        if profile_result:
            report += "![Line profile](profile.png)\n\n"
        report += "![Full FFT magnitude display](fft.png)\n"
        report += "\n## Numeric outputs\n\n"
        report += "- Statistics: `stats.json`.\n- Full shifted absolute FFT magnitude: `fft_magnitude.npy`; axes and peak samples: `fft.json`.\n"
        if profile_result:
            report += "- Profile samples: `profile.csv` and `profile.json`.\n"
        report += "\n\n## Interpretation\n\n"
        report += "The statistics and profile describe raw captured pixel values. Intensity scale/origin/unit are retained as metadata, not applied; these values are not labeled as calibrated counts or another physical intensity unit. FFT peaks are frequency-grid samples from the complete computed spectrum; this report does not identify reflections, lattice planes, phases, or atomic spacings.\n"
        report += "\n## Human review\n\n"
        report += "Check the selection overlay against the input preview and confirm the physical calibration and feature assignment before drawing scientific conclusions. Capture descriptors were stable, but the DM API does not provide an atomic pixel-plus-calibration snapshot; the source image must not be edited during capture.\n"
        report += "\n## Reproduction\n\n"
        report += "Install Python 3.10+ with NumPy, Matplotlib, and Pillow, then run `python replay.py --verify` to recompute and compare numeric outputs, or `python replay.py --output NEW_EMPTY_DIRECTORY` to regenerate a result bundle.\n"
        report += "\nThe bundle contains only the captured selection and required calibration, not the original file path or full metadata tree. If submitted to a hosted agent, the image preview, selected coordinates, calibration, and returned values may be sent to that model service.\n"
        with open(os.path.join(result_dir, "report.md"), "x", encoding="utf-8", newline="\n") as stream:
            stream.write(report)
        _write_json(os.path.join(result_dir, "environment.json"), env)
        shutil.copyfile(CORE_PATH, os.path.join(result_dir, "analysis2d_core.py"))
        shutil.copyfile(os.path.abspath(__file__), os.path.join(result_dir, "analysis_worker.py"))
        replay = '''# -*- coding: utf-8 -*-\nimport json, os, subprocess, sys\nroot = os.path.dirname(os.path.abspath(__file__))\naction = "verify"\noutput = None\nif len(sys.argv) == 3 and sys.argv[1] == "--output":\n    action, output = "replay", os.path.abspath(sys.argv[2])\nelif len(sys.argv) != 2 or sys.argv[1] != "--verify":\n    raise SystemExit("usage: python replay.py --verify | --output NEW_EMPTY_DIRECTORY")\nrequest = {"action": action, "bundle_dir": root, "output_dir": output}\nresult = subprocess.run([sys.executable, os.path.join(root, "analysis_worker.py")], input=json.dumps(request), text=True, capture_output=True)\nprint(result.stdout, end="")\nif result.returncode:\n    print(result.stderr, file=sys.stderr)\nraise SystemExit(result.returncode)\n'''
        with open(os.path.join(result_dir, "replay.py"), "x", encoding="utf-8", newline="\n") as stream:
            stream.write(replay)
        manifest.update({"state": "succeeded", "completed_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                         "outputs": _output_hashes(result_dir),
                         "numerical_contract": {"stats": "float64 finite values; population stddev ddof=0",
                                                "profile": "shared bilinear interpolation kernel",
                                                "fft": "full shifted absolute magnitude from shared kernel",
                                                "replay_rtol": 1e-10, "replay_atol": 1e-12}})
        _atomic_manifest(manifest_path, manifest)
        return {"state": "succeeded", "operation_id": operation_id,
                "result_dir": result_dir, "capture_id": info["capture_id"],
                "request_sha256": request_hash, "stats": stats,
                "profile_points": profile_result["n"] if profile_result else None,
                "fft_shape_yx": list(fft_values.shape),
                "files": sorted(manifest["outputs"])}
    except Exception as exc:
        manifest.update({"state": "failed", "error": str(exc),
                         "failed_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                         "outputs": _output_hashes(result_dir)})
        _atomic_manifest(manifest_path, manifest)
        raise


def _verify_bundle(bundle_dir):
    bundle = os.path.abspath(bundle_dir)
    manifest = _read_json(_manifest_path(bundle))
    if manifest.get("state") != "succeeded":
        return {"state": "unknown" if manifest.get("state") == "running" else manifest.get("state"),
                "operation_id": manifest.get("operation_id")}
    actual = _output_hashes(bundle)
    if actual != manifest.get("outputs"):
        return {"state": "failed", "error": "bundle output checksum mismatch"}
    info = _read_json(os.path.join(bundle, "input.json"))
    request = _read_json(os.path.join(bundle, "request.json"))
    array = np.load(os.path.join(bundle, "input.npy"), mmap_mode="r", allow_pickle=False)
    roi = request["params"]["roi_source_xyxy"]
    rel = _relative_roi(roi, info["source_rect_xyxy"])
    x0, y0, x1, y1 = rel
    selected = array[y0:y1, x0:x1]
    stats = core.statistics(selected)
    stats.update({"roi_source_xyxy": roi, "roi_local_xyxy": rel,
                  "shape_yx": list(selected.shape),
                  "calibration_xy": _local_calibration(info, rel[0], rel[1]),
                  "intensity_calibration": info.get("intensity_calibration"),
                      "intensity_value_mode": "raw pixel values; intensity calibration retained but not applied",
                  "finite_policy": "finite pixels only; NaN/Inf excluded and separately counted; population stddev ddof=0; zero values retained"})
    saved_stats = _read_json(os.path.join(bundle, "stats.json"))
    good, why = _recursive_numeric_equal(stats, saved_stats)
    if not good:
        return {"state": "failed", "error": "statistics replay mismatch at " + why}
    profile_request = request["params"].get("profile_source")
    if profile_request:
        profile = _profile_result(array, info, profile_request)
        good, why = _recursive_numeric_equal(profile, _read_json(os.path.join(bundle, "profile.json")))
        if not good:
            return {"state": "failed", "error": "profile replay mismatch at " + why}
    fft_result, fft_values = core.fft(selected, _local_calibration(info, rel[0], rel[1]), request["params"]["top_n"])
    fft_result.update({"roi_source_xyxy": roi, "roi_local_xyxy": rel,
                       "shape_yx": list(fft_values.shape),
                       "axes": _calibrated_fft_metadata(fft_result["calibration"], fft_values.shape)})
    good, why = _recursive_numeric_equal(fft_result, _read_json(os.path.join(bundle, "fft.json")))
    if not good:
        return {"state": "failed", "error": "FFT replay metadata mismatch at " + why}
    expected_fft = np.load(os.path.join(bundle, "fft_magnitude.npy"), mmap_mode="r", allow_pickle=False)
    if not np.allclose(fft_values, expected_fft, rtol=1e-10, atol=1e-12, equal_nan=False):
        return {"state": "failed", "error": "FFT replay array mismatch outside rtol=1e-10, atol=1e-12"}
    return {"state": "verified", "operation_id": manifest.get("operation_id"),
            "numeric_checks": ["statistics", "profile", "FFT metadata", "full FFT magnitude"],
            "tolerance": {"rtol": 1e-10, "atol": 1e-12},
            "images": "PNG bytes are not compared; numeric source and parameters are recomputed"}


def inspect_result(payload, expected_operation_id=None):
    if payload.get("capture_dir"):
        folder = os.path.abspath(payload["capture_dir"])
        try:
            capture = _read_json(os.path.join(folder, "capture.json"))
        except Exception:
            return {"state": "unknown", "capture_dir": folder,
                    "note": "capture manifest is absent or unreadable; do not automatically repeat capture"}
        state = capture.get("state")
        return {"state": "unknown" if state == "capturing" else state or "unknown",
                "capture_id": capture.get("capture_id"), "capture_dir": folder,
                "input_sha256": capture.get("input_sha256"),
                "note": "capture status only; source pixels and calibration are not an atomic snapshot"}
    folder = os.path.abspath(payload["result_dir"])
    try:
        manifest = _read_json(_manifest_path(folder))
    except Exception:
        return {"state": "unknown", "result_dir": folder,
                "note": "analysis manifest is absent or unreadable; do not automatically repeat analysis"}
    if expected_operation_id and manifest.get("operation_id") != expected_operation_id:
        raise ValueError("result_dir operation_id mismatch")
    state = manifest.get("state")
    if state == "running":
        return {"state": "unknown", "operation_id": manifest.get("operation_id"),
                "result_dir": folder, "note": "manifest is still running; do not automatically repeat the analysis"}
    if state == "succeeded":
        actual = _output_hashes(folder)
        if actual != manifest.get("outputs"):
            return {"state": "failed", "operation_id": manifest.get("operation_id"),
                    "result_dir": folder, "error": "output checksum mismatch"}
        return {"state": "succeeded", "operation_id": manifest.get("operation_id"),
                "result_dir": folder, "capture_id": manifest.get("capture_id"),
                "outputs": manifest.get("outputs"), "request_sha256": manifest.get("request_sha256")}
    return {"state": state or "unknown", "operation_id": manifest.get("operation_id"),
            "result_dir": folder, "error": manifest.get("error")}


def replay_bundle(payload):
    bundle = os.path.abspath(payload["bundle_dir"])
    action = payload.get("action")
    if action == "verify":
        return _verify_bundle(bundle)
    if action == "replay":
        out = payload.get("output_dir")
        if not out:
            raise ValueError("replay requires a new output_dir")
        request = _read_json(os.path.join(bundle, "request.json"))
        params = request["params"]
        return _compute(bundle, {"roi": params["roi_source_xyxy"],
                                 "profile": params.get("profile_source"), "top_n": params["top_n"]},
                        out, "replay-" + uuid.uuid4().hex)
    raise ValueError("unknown replay action")


def main():
    request = json.loads(sys.stdin.read())
    action = request.get("action")
    if action == "preview":
        result = preview(request)
    elif action == "analyze":
        operation_id = request.get("operation_id")
        if not isinstance(operation_id, str) or not operation_id.strip() or len(operation_id) > 128:
            raise ValueError("operation_id must be a nonempty string up to 128 characters")
        result = _compute(request["capture_dir"], request, request["result_dir"], operation_id)
    elif action == "result":
        result = inspect_result(request)
    elif action in ("verify", "replay"):
        result = replay_bundle(request)
    else:
        raise ValueError("unknown worker action")
    successful = action != "verify" or result.get("state") == "verified"
    reply = {"ok": successful, "result": result}
    if not successful:
        reply["error"] = result.get("error") or "verification did not complete: %s" % result.get("state")
    sys.stdout.write(json.dumps(reply, ensure_ascii=False, allow_nan=False) + "\n")
    return 0 if successful else 1


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:
        sys.stdout.write(json.dumps({"ok": False, "error": str(exc)}, ensure_ascii=False) + "\n")
        sys.exit(2)
